def digest(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()


def setup():
    root = Path.cwd()
    if not (root / 'healthbot').is_dir():
        raise SystemExit('Exécuter depuis la racine ~/ChatBotHealthCare.')
    script = root / 'scripts/validation_healthcare.py'
    if not script.is_file():
        raise SystemExit('scripts/validation_healthcare.py introuvable.')
    api = runpy.run_path(str(script), run_name='validation30_support')
    _, cfg = api['root_and_config']()
    return root, cfg, api


def prepare(root, cfg):
    target = root / 'data/evaluation/evaluation_30_proposee.json'
    review = root / 'artifacts/evaluation_30_relecture.md'
    if target.exists() or review.exists():
        raise SystemExit('Jeu ou fiche de relecture déjà présent : aucun écrasement.')
    corpus_path = Path(cfg['corpus'])
    rows = [json.loads(line) for line in corpus_path.read_text(encoding='utf-8').splitlines() if line.strip()]
    by_id = {row['id']: row for row in rows}
    for case in DATA['cases']:
        if case['category'] != 'covered':
            continue
        docid = case['relevant_documents'][0]
        if docid not in by_id:
            raise SystemExit('Document manquant : ' + docid)
        row = by_id[docid]
        if ' '.join(row['text'].split()) != ' '.join(case['reference_text'].split()):
            raise SystemExit('Texte différent du document fourni : ' + docid)
        if row.get('approved') is not True:
            raise SystemExit('Document non activé dans le corpus : ' + docid)
        case['source_url'] = row.get('source_url', '')
    DATA['corpus_sha256'] = digest(corpus_path)
    target.parent.mkdir(parents=True, exist_ok=True)
    review.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(json.dumps(DATA, ensure_ascii=False, indent=2)+'\n', encoding='utf-8')
    lines = ['# Évaluation proposée : 30 cas, 25 actifs', '',
             'Relire les questions et les preuves. reviewed=true signifie annotation relue, pas validation clinique.',
             'Les cinq U restent exclus. Un échec de recherche ne prouve pas une absence du corpus.',
             'Pour le rewriting : vérifier sujet, intention, négations et absence de détails ajoutés.',
             'Pour les réponses : juger fidélité, pertinence, citations et langue séparément du statut.', '']
    for c in DATA['cases']:
        lines += [f"## {c['id']} — {c['category']}", c['question'], '', c['review_note'], '']
        if c['category'] == 'covered':
            lines += ['Document : '+c['relevant_documents'][0], 'Titre : '+c['original_question'],
                      'Source : '+c.get('source_url',''), '', 'Passages de preuve :']
            lines += ['> '+q for q in c['evidence_quotes']]
            lines += ['', 'Texte complet :', c['reference_text'], '']
    review.write_text('\n'.join(lines), encoding='utf-8')
    print('Créé :', target)
    print('Relecture :', review)
    print('25 cas actifs provisoires ; 5 cas U exclus en attente de vérification.')


def run(root, cfg, api, answers):
    path = root / 'data/evaluation/evaluation_30_proposee.json'
    data = json.loads(path.read_text(encoding='utf-8'))
    if digest(Path(cfg['corpus'])) != data['corpus_sha256']:
        raise SystemExit('Corpus changé : réviser les annotations avant de poursuivre.')
    cases = [c for c in data['cases'] if c.get('enabled') and c['category'] != 'medical_absence_unverified']
    if len(cases) != 25:
        raise SystemExit('Ce lanceur attend 25 cas actifs ; les 5 cas U nécessitent un protocole distinct après audit.')
    # Le script existant ne calcule pas les métriques des cas U : ne jamais les activer silencieusement.
    data['cases'] = cases
    data['scope'] += ' E5 seul ; 25 actifs sur 30 proposés ; reranking et rewriting non évalués par ce lanceur.'
    active = root / 'artifacts/evaluation_30_active.json'
    active.parent.mkdir(parents=True, exist_ok=True)
    active.write_text(json.dumps(data, ensure_ascii=False, indent=2)+'\n', encoding='utf-8')
    baseline = dict(cfg, retriever='dense')
    print('BASELINE E5 : top_k =', baseline['top_k'], '; modèle =', baseline.get('ollama_model'))
    print('25 cas actifs ; 5 questions U exclues. Annotations proposées, non validées cliniquement.')
    api['run'](root, baseline, active, answers, False)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('command', choices=['prepare','run'])
    parser.add_argument('--answers', action='store_true')
    args = parser.parse_args()
    root, cfg, api = setup()
    if args.command == 'prepare':
        prepare(root, cfg)
    else:
        run(root, cfg, api, args.answers)


if __name__ == '__main__':
    main()
